CREATE FUNCTION public.mastery_identity_sources(p_sport text,p_date date,p_athlete uuid DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE athlete uuid:=coalesce(p_athlete,auth.uid()); answer jsonb; BEGIN IF auth.uid() IS NULL OR p_sport NOT IN ('baseball','softball') OR p_date IS NULL OR NOT public._coach_training_access(athlete) THEN RAISE EXCEPTION 'not authorized' USING ERRCODE='42501'; END IF; IF athlete<>auth.uid() AND NOT EXISTS(SELECT 1 FROM public.athlete_context WHERE user_id=athlete AND sport_primary=p_sport) THEN RAISE EXCEPTION 'sport not shared' USING ERRCODE='42501'; END IF; SELECT jsonb_build_object('atBats',coalesce((SELECT jsonb_agg(jsonb_build_object('id',a.id,'result',a.result,'date',g.game_date,'game_id',g.id,'order',coalesce(a.inning,0)*10000+coalesce(a.ab_order,0),'source',coalesce(a.entry_source,'Source not recorded')) ORDER BY g.game_date,g.id,a.inning,a.ab_order,a.id) FROM public.gp_at_bats a JOIN public.gp_games g ON g.id=a.game_id WHERE a.user_id=athlete AND g.user_id=athlete AND g.sport=p_sport AND g.deleted_at IS NULL AND g.ignored_for_training=false AND g.status IN ('completed','final') AND g.game_date<p_date),'[]'::jsonb),'tests',coalesce((SELECT jsonb_agg(jsonb_build_object('id',t.id,'date',t.test_date,'type',t.test_type,'results',t.results) ORDER BY t.test_date,t.id) FROM public.vault_performance_tests t WHERE t.user_id=athlete AND t.sport=p_sport AND t.test_date<p_date),'[]'::jsonb),'sprints',coalesce((SELECT jsonb_agg(jsonb_build_object('id',s.id,'date',s.plan_date,'metrics',s.metrics,'distance',s.distance_feet_completed) ORDER BY s.plan_date,s.id) FROM public.wk_session_logs s WHERE s.user_id=athlete AND s.metrics->>'sport'=p_sport AND s.metrics->>'kind'='sprint_time' AND s.plan_date<p_date),'[]'::jsonb),'runs',coalesce((SELECT jsonb_agg(jsonb_build_object('id',r.id,'date',g.game_date,'type',r.event_type,'seconds',r.run_time_sec,'lead_steps',r.lead_steps,'source',coalesce(r.entry_source,'Source not recorded')) ORDER BY g.game_date,r.id) FROM public.gp_baserun_events r JOIN public.gp_games g ON g.id=r.game_id WHERE r.user_id=athlete AND g.user_id=athlete AND g.sport=p_sport AND g.deleted_at IS NULL AND g.ignored_for_training=false AND g.status IN ('completed','final') AND g.game_date<p_date),'[]'::jsonb),'homeFirst',coalesce((SELECT jsonb_agg(jsonb_build_object('id',a.id,'date',g.game_date,'seconds',a.h1_time_sec,'side',a.batting_side,'source',coalesce(a.entry_source,'Source not recorded')) ORDER BY g.game_date,a.id) FROM public.gp_at_bats a JOIN public.gp_games g ON g.id=a.game_id WHERE a.user_id=athlete AND g.user_id=athlete AND g.sport=p_sport AND a.h1_time_sec IS NOT NULL AND g.deleted_at IS NULL AND g.ignored_for_training=false AND g.status IN ('completed','final') AND g.game_date<p_date),'[]'::jsonb),'royal',coalesce((SELECT jsonb_agg(jsonb_build_object('id',r.id,'date',r.created_at,'timers',r.timer_data) ORDER BY r.created_at,r.id) FROM public.royal_timing_sessions r WHERE r.user_id=athlete AND r.sport=p_sport AND r.created_at::date<p_date),'[]'::jsonb)) INTO answer; RETURN answer; END $$; REVOKE ALL ON FUNCTION public.mastery_identity_sources(text,date,uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.mastery_identity_sources(text,date,uuid) TO authenticated,service_role; COMMENT ON FUNCTION public.mastery_identity_sources(text,date,uuid) IS 'Complete self/sport history and narrow training-authorized coach history; raw speed sources stay separate. No private analysis or health data.';